#!/usr/bin/env python3
from pathlib import Path
import base64
ROOT = Path(__file__).resolve().parents[1]

def dec(s): return base64.b64decode(s.encode()).decode()
def replace_once(path, old, new, label):
    p=ROOT/path; text=p.read_text(); count=text.count(old)
    if count != 1: raise SystemExit(f"{label}: expected one anchor in {p}, found {count}")
    p.write_text(text.replace(old,new,1)); print(f"patched {label}: {p}")
def replace_all(path, old, new, label):
    p=ROOT/path; text=p.read_text(); count=text.count(old)
    if count < 1: raise SystemExit(f"{label}: anchor missing in {p}")
    p.write_text(text.replace(old,new)); print(f"patched {label}: {p} ({count} replacements)")
def require(path, needle, label):
    p=ROOT/path; text=p.read_text()
    if needle not in text: raise SystemExit(f"{label}: missing {needle!r} in {p}")

